+      return { agentSpendNanos: value.agentSpendNanos ?? 0, detailNanos: value.detailNanos ?? {} };
+    } catch { return { agentSpendNanos: 0, detailNanos: {} }; }
+  }
+
+  private saveWriteback(): void {
